// Offline demonstration content: the generated bytes are a validated published
// catalog, not hand-written UI fixtures. Only the explicit demo build imports it.
import { demoFiles } from './demoCatalog.generated.ts';

const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

export function decodeDemoBytes(value: string): Uint8Array {
  if (!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(value)) {
    throw new Error('demo-base64-invalid');
  }
  const padding = value.endsWith('==') ? 2 : value.endsWith('=') ? 1 : 0;
  const bytes = new Uint8Array(value.length / 4 * 3 - padding);
  let cursor = 0;
  for (let at = 0; at < value.length; at += 4) {
    const a = alphabet.indexOf(value[at]);
    const b = alphabet.indexOf(value[at + 1]);
    const c = value[at + 2] === '=' ? 0 : alphabet.indexOf(value[at + 2]);
    const d = value[at + 3] === '=' ? 0 : alphabet.indexOf(value[at + 3]);
    const word = (a << 18) | (b << 12) | (c << 6) | d;
    bytes[cursor++] = word >>> 16;
    if (cursor < bytes.length) bytes[cursor++] = (word >>> 8) & 255;
    if (cursor < bytes.length) bytes[cursor++] = word & 255;
  }
  return bytes;
}

export async function loadDemoBytes(path: string): Promise<Uint8Array> {
  const encoded = demoFiles[path];
  if (encoded === undefined) throw new Error('demo-file-unavailable');
  return decodeDemoBytes(encoded);
}

export async function loadDemoText(path: string): Promise<string> {
  return new TextDecoder().decode(await loadDemoBytes(path));
}
